public class Trigonom {
  public static void main(String[] args) {
      double[] arr = {Math.PI/2, Math.PI/3, Math.PI/4, Math.PI/5};
      double[] senos = new double[4];

      // La API Math de Java está diseñada de manera escalar (Uno por uno)
      for(int i = 0; i < arr.length; i++) {
          senos[i] = Math.sin(arr[i]);
      }

      System.out.println(java.util.Arrays.toString(senos));
  }
}
